-- Stanze pubbliche piu' grandi, come i locali di Habbo, e quattro locali nuovi:
-- spiaggia, edicola, cinema e palestra. Pianta e arredi sono generati da
-- BE/scripts/hotel_rooms.py, che controlla anche che ogni casella sia raggiungibile.

-- I pacchetti comprati in edicola finiscono nella borsa (user_pack_credits).
ALTER TABLE user_wallet_transactions DROP CONSTRAINT ck_wallet_tx_type;
ALTER TABLE user_wallet_transactions ADD CONSTRAINT ck_wallet_tx_type CHECK (type IN (
    'PACK_OPEN_PAID', 'PACK_OPEN_FREE', 'MARKET_SALE', 'MARKET_PURCHASE', 'TRADE',
    'MISSION_REWARD', 'LEVEL_REWARD', 'ALBUM_REWARD', 'DAILY_LOGIN', 'BATTLE_REWARD', 'ADMIN_ADJUST',
    'FURNI_PURCHASE', 'PVP_REWARD', 'PACK_PURCHASE'));

-- Gli arredi fissi delle stanze pubbliche si rifanno da capo.
